review_comment:
```suggestion
    @functools.cached_property
    def context(self):
        """
        Hidden property for storing runtime context during credential resolution.
        """
        return {}
```

A generator expression seems a bit more elegant here
```suggestion
        return next(
            (
                cred for cred in self._credentials
                if cred.credential_type.kind == 'ssh'
            ),
            None,
        )
```

Seeing that there's no args being accepted, I'd turn this and the others into properties like so:
```suggestion
    @property
    def _machine_credential(self):
```

Actually... This can also be deduplicated a bit + add some (incomplete) typing:
```suggestion
    from collections import abc as _abc

    @property
    def _extract_credentials_of_kind(self, kind: str, /) -> _abc.Iterator[object]:
        """Get machine credential."""
        return (cred for cred in self._credentials if cred.credential_type.kind == kind)

    @property
    def _machine_credential(self) -> object:
        """Get machine credential."""
        return next(self._extract_credentials_of_kind('ssh'), None)

    @property
    def _vault_credentials(self) -> list[object]:
        """Get vault credentials."""
        return list(self._extract_credentials_of_kind('vault'))

    @property
    def _network_credentials(self) -> list[object]:
        """Get network credentials."""
        return list(self._extract_credentials_of_kind('net'))

    @property
    def _cloud_credentials(self) -> list[object]:
        """Get cloud credentials."""
        return list(self._extract_credentials_of_kind('cloud'))
```

